"nota.dados_aria": "数据说明{id}：{titulo}",
"como.fatia.tit": "占比的计算方法",
"como.fatia.1": "**卢拉占比**（卢拉在两人合计票数中的占比）= 卢拉的票数 ÷（卢拉的票数 + 弗拉维奥的票数）。弗拉维奥的占比为100%减去卢拉的占比。",
"como.fatia.2": "全国，第二轮：{l2} ÷ {dois} = {s2}。",
"como.fatia.3": "首轮中其他候选人的得票不计入。来源：巴西高等选举法院（TSE），首轮和第二轮投票结果。",
"como.diferenca.tit": "票差的计算方法",
"como.diferenca.1": "**票差** = 卢拉的票数 − 弗拉维奥的票数，每轮分别计算。弗拉维奥得票较多时为负数。",
"como.diferenca.2": "全国：首轮{m1}；第二轮{m2}。从首轮到第二轮的变化：{dm}票。",
"como.diferenca.3": "这是完整计票，没有误差范围。来源：巴西高等选举法院（TSE）。",
"como.captura.tit": "新增票占比的计算方法",
"como.captura.1": "**新增票占比**（卢拉在两人新增票数中的占比）= 从首轮到第二轮卢拉增加的票数 ÷ 两人增加的票数。",
"como.captura.2": "全国：{dl} ÷ {dois} = {cap}。弗拉维奥的部分为{capf}。",
"como.captura.3": "两人合计没有新增票的地方无此值（注释N09）。",
"como.fontes.tit": "新增票来源的计算方法",
"como.fontes.1": "从首轮到第二轮，卢拉和弗拉维奥合计增加的票数是三部分之和：投票人数的增加、其他候选人在首轮的得票（第二轮只有两人），以及空白票和无效票的减少。",
"como.fontes.2": "全国：{c} + {o} + {b} = {n}。",
"como.fontes.3": "这是加法运算，不是估计，而且只说明净变化：数据显示的不是个人。首轮投票的人中，可能有一部分第二轮没有投票，由首轮没有投票的人替代。每一部分如何在两人之间分配属于估计，见第3章。",
"como.ecologica.tit": "选票从哪里来：如何估计",
"como.ecologica.1": "用生态回归估计：全国层面使用{mun}个市镇，各地则比较同一城市内的投票站。比较每种新增票来源的数量与两人各自在第二轮增加的票数。",
"como.ecologica.2": "它说明的是净变化，而不是每位选民的投票路径。检验和稳健性检验见第3章。",
