"funil.leitura": "颜色较深的区间带表示按模型每种规模的市镇中95%会落在的范围；颜色较浅的为{p998}。小市镇仅仅因为规模小，变化就更大：小城市排行榜的前几名本身并不构成规律。区间带来自模型：显示这种规模的市镇通常的变化幅度。",
