"funil.leg_abaixo": {"t": "下方区间带外：弗拉维奥的", "rotulo": 32},
"funil.dica_fatia": {"t": "卢拉占比的变化", "rotulo": 30},
"funil.dica_abstencao": {"t": "弃权率的变化", "rotulo": 30},
"funil.fonte": "来源：巴西高等选举法院（TSE），按市镇的投票结果；区间带采用Spiegelhalter（2005a，2005b）的模型；本研究计算。",
"funil.como.tit": "漏斗图区间带的计算方法",
"funil.como.1": "中心：全部{mun}个市镇合计的变化。区间带：中心 ± z × √(随机误差² + τ²)，其中随机误差只取决于合格选民人数，τ²是所有市镇共有的变化，由数据估计（95%时z = {z95}，{p998}时z = {z998}）。",
"funil.como.2": "按照模型，约5%的市镇会因随机原因落在95%区间带之外；实际为{fora}，各规模组为{pmin}至{pmax}。τ²用全部市镇估计，不截去两端；若像原方法那样两端各截去10%，中型和大型市镇的区间带会过窄，落在区间带外的将有{fw}。当变化取决于规模时，假设所有市镇共有同一种变化是一种简化（Xia et al.，2022）。",
"funil.como.2_abst": "在弃权率方面，95%区间带之外的{fora95}个市镇中，有{acima}个位于区间带上方：分布的上尾较长，对称的区间带不适用。点位于区间带上方，表示弃权率的上升幅度大于该规模的大多数市镇，而不表示这种情况有多罕见。",
"funil.como.3": "局限：区间带来自模型，用于筛选，以决定哪些需要仔细查看（Spiegelhalter et al.，2012）；一个市镇落在区间带外，本身并不能证明任何事。",

