"c1.pergunta": "卢拉在哪里增长更多：原本强的地方，还是原本弱的地方？",
"c1.curto": {"t": "卢拉在哪里增长更多", "rotulo": 30},
"c1.resposta": "在原本较弱的地方。比较同一州内的市镇，卢拉在首轮的占比越高，增幅越小：每高10个百分点，增幅少{pts}。弗拉维奥也是如此：两人都在原本较弱的地方增长更多。",
"c1.hipotese": "每位候选人在首轮较弱的地方，在两人中的占比增加更多（或减少更少）。",
"c1.fig1.titulo": "两人都在首轮占比较低的地方增长更多",
"c1.fig1.sub": "在{mun}个市镇中，卢拉在两人中的占比从首轮到第二轮的变化（纵轴）与他在首轮的占比（横轴）。每个圆圈代表一个市镇，大小对应合格选民人数；颜色显示卢拉的占比是上升（红色）还是下降（蓝色），不表示谁在该市镇得票更多。左侧是首轮弗拉维奥占比较高的市镇。",
"c1.fig1.aria": "{mun}个市镇的散点图：横轴为卢拉在首轮的占比，纵轴为他的占比变化。趋势从左向右下降：卢拉在首轮占比已经较高的地方，增幅较小。",
"c1.dica.fatia1": {"t": "卢拉首轮占比", "rotulo": 30},
"c1.fig1.eixo_x": {"t": "卢拉首轮占比（弗拉维奥＝100%−卢拉）", "rotulo": 64},
"c1.fig1.rot_acima": {"t": "零线以上：卢拉的占比上升", "rotulo": 40},
"c1.fig1.rot_acima_curto": {"t": "上方：卢拉的上升", "rotulo": 32},
"c1.fig1.rot_abaixo": {"t": "零线以下：弗拉维奥的占比上升", "rotulo": 40},
"c1.fig1.rot_abaixo_curto": {"t": "下：弗拉维奥升", "rotulo": 32},
// a anotação dentro do gráfico, uma linha por item (no computador e no celular)
"c1.fig1.anotacao": ["卢拉原本占比较高的地方，", "增幅较小"],
"c1.fig1.anotacao_cel": ["卢拉原本", "占比较高处", "增幅较小"],
"c1.fig1.como1": "**卢拉占比** = 卢拉的票数 ÷（卢拉的票数 + 弗拉维奥的票数）。变化为第二轮占比减去首轮占比，单位为百分点。弗拉维奥的变化数值相同，符号相反。",
"c1.fig1.como2": "例如全国：首轮{s1}，第二轮{s2}，变化{ds}",
"c1.fig1.como3": "这条线是所有市镇合并、按合格选民人数加权得出的趋势：每10个百分点对应{coef}个百分点。起决定作用的检验比较同一州内的市镇，见“查看详情”。",
"c1.fig1.como4": "局限：这是市镇之间的关联，不能说明每位选民如何投票。",
"c1.lado.tit": "如何解读",
"c1.lado.1": "即使行为没有任何变化，这个方向也在预料之中：一位候选人已经得票很多的地方，增长空间较小。关键在于下降的幅度，见“查看详情”。",
"c1.lado.2": "这种关联是市镇之间的关联，不能说明每位选民如何投票。",
"c1.chegou.texto": "卢拉占比在首轮占比较低的地方上升更多。对两人同样表述：每位候选人在首轮较弱的地方，占比增加更多（或减少更少）。",
"c1.chegou.porque": "**为什么是这个方向：**在一个简单模型中，如果新增票数的净变化在各地按同一比例分配，候选人原本较强的地方，占比上升较少。在全国，两人新增的票数中有{cap}归卢拉（新增票占比{nota}），高于他在首轮的占比（{s1}）。如果新增票多数归弗拉维奥，同样的计算会预测相反的方向，预期的假设也会换成他的一方。",
"c1.chegou.variavel": "他在首轮的占比",
"c1.texto.1": "比较同一州内的市镇：卢拉首轮占比每高10个百分点，他的占比从首轮到第二轮的上升就少{pts}（{ic0}至{ic1}）。最低四分位的市镇与最高四分位的市镇之间，差距为{iq}个百分点。就全国整体而言，方向相同（每10个百分点{br}个百分点）。",
"c1.texto.2": "**按占合格选民的比例计票数：**弗拉维奥在原本较强的地方新增票数更多（他首轮占比每高10个百分点，新增票数多出合格选民的{cf}个百分点，{cf0}至{cf1}）；卢拉新增的票数与他原有的占比没有同步变化（{cl0}至{cl1}）。",
"c1.texto.3": "**局限：**即使新增票在各地以同样方式分配，也会出现这个方向；这种关联是市镇之间的关联，不能说明每位选民如何投票。",
"c1.texto.4": "**与均等分配对比（探索性，未在计算前登记；在统计评审意见之后计算）：**如果两人新增票数的净变化在每个市镇都按全国的比例分配（卢拉{cap}，不含海外票，海外票不在市镇之间的计算之内），同样的计算会得出每10个百分点{esp}个百分点（{esp0}至{esp1}）；实际观察到的是{obs}。占比的下降约为均等分配所得的一半：在每位候选人原本较强的地方，他获得的净变化份额高于全国水平。这对两人同样适用，因为是同一个计算。部分下降可能来自均值回归（Barnett、van der Pols和Dobson，2005）：当首轮占比含有暂时性成分时，斜率会比实际更负；由于计票完整且按合格选民人数加权，这一效应应该很小，而且它只会使这一差距更大。",
"c1.funil.secao": "市镇仅因规模小而产生的波动有多大",
"c1.funil.titulo": "小市镇仅因规模小而波动更大",
"c1.funil.sub": "卢拉占比的变化（纵轴）与市镇合格选民人数（横轴），以及模型对每种规模预期的范围。",
"c1.funil.texto": "共有{n}个市镇落在{p998}范围之外：其中{acima}个是卢拉占比的变化高于范围；{abaixo}个是弗拉维奥占比的变化高于范围。",
"c1.rank.secao": "卢拉占比上升最多的地方",
"c1.rank.titulo": "合格选民超过1万的市镇中，卢拉占比上升最多的10个",
"c1.rank.nota": "以百分点计的排名只包括合格选民超过1万的市镇，以免小市镇的波动主导名单（门槛事先设定；完整排名见“探索”标签页）。",

