"c4.fig2.fonte": "来源：巴西高等选举法院（TSE），按投票站的结果；比较同一市镇内投票站的生态回归，按地区和州；本研究计算。",
"c4.fig2.como1": "**与第3章相同的生态回归**，但比较同一市镇内的投票站（{sec}个投票站），并加入市镇效应：影响整个市镇的因素被排除在计算之外，只计同一市镇内投票站之间的差异。按地区和州分别计算。区间用自助法：全国和各地区对整州重抽样；各州内对整个市镇重抽样，连同其所有投票站。因此，“每多100名投票者”是就同一市镇内投票站的比较而言。变化中有一部分是整个市镇共有的，与三种来源都不同步：在全国，相抵后卢拉多{comum}票，占第二轮新增票数的{pct}。这部分不在分配之内。",
"c4.fig2.como2": "**精度标准**，对两人相同：至少30个市镇；估计值在0%至100%之间（超出时，模型不能描述该地方，该地方的所有来源都标上†）；95%置信区间的半宽不超过10个百分点。未通过时，显示原因。",
"c4.fig2.como3": "只有当整个区间都高于50%时，才说“大部分归X”。",
"c4.fig2.como4": "**稳健性检验**，事先登记，不改变解读：去掉两轮之间合格选民人数变化超过5人的投票站（注释{n22}）、去掉接收了合并投票站的投票站、不加权，以及换一次区间抽样。所有检验下，{total}个地方中有{n}个的解读保持不变，全国在其中。不加市镇效应时，投票站的计算重复了市镇之间计算的结果，包括超出0%至100%的估计值：改变答案的是比较同一市镇内的投票站。28号候选人的被撤销选票计为无效票（注释{n21}）。",
"c4.fig2.como5": "**市镇之间的计算**（这张图以前显示的内容）列在旁边“查看详情”的表格中。它在{muda}把大部分给了两人之一；比较投票站时，这些州无明确一方。",
"c4.lado.tit": "两个层次",
"c4.lado.1": "第一层是计数：弃权率在哪里上升、在哪里下降，没有误差范围。第二层是估计：投票人数净变化流向哪里，只在通过事先设定的精度标准的地方显示。",
"c4.lado.2": "一个市镇的合格选民在两轮之间会变化，投票人数的部分变化可能来自在另一轮于别处投票的选民。",
"c4.chegou.texto": "在弃权率下降较多的地方，卢拉占比上升更多（弗拉维奥占比下降更多）。",
"c4.chegou.porque": "**为什么是这个方向：**按照第1章的同一个简单模型：如果一位候选人在新增票中所占的部分（在全国，卢拉为{cap}）高于他的占比，那么在新增票较多的地方，例如新来投票者较多的地方，他的占比上升更多。如果新增票多数归弗拉维奥，预测就会相反。",
"c4.chegou.variavel": "弃权率的变化",
"c4.texto.1": "占比的变化与弃权率的变化没有明显的同步关系：所有版本的区间都包含零（在州内，弃权率每变化1个百分点，占比变化{ic0}至{ic1}个百分点）。",
"c4.texto.2": "**按票数计：**两人都在弃权率下降较多的地方新增了更多票数。比较同一州内的市镇，弃权率每低1个百分点，卢拉的新增票数多出合格选民的{cl}个百分点（{cl0}至{cl1}），弗拉维奥多出{cf}个百分点（{cf0}至{cf1}）。",
"c4.texto.3": "**局限：**一个市镇的合格选民在两轮之间会变化{n05}，投票人数的部分变化可能来自在另一轮于别处投票的选民。",
