// ======================= Capítulo 5 =======================
"c5.pergunta": "众议员和参议员选举的投票与两轮之间的变化有关联吗？",
"c5.curto": {"t": "众议员、州议员和参议员", "rotulo": 30},
"c5.resposta": "没有看到明确的关联，卢拉一方和弗拉维奥一方都是如此。在联邦众议员选举中本来更多投给左翼政党的地方，与同一州内首轮卢拉占比相同的市镇相比，卢拉的增长并没有明显更多；在更多投给右翼政党的地方，弗拉维奥也是如此。即使存在关联，也很小。州议员和参议员选举的情况相同。",
"c5.resposta.ic": "{a}至{b}个百分点",
"c5.hipotese": "在众议员或参议员选举中本来投票给左翼阵营政党、但在首轮总统选举中没有投给卢拉的地方，卢拉在第二轮增长更多。",
"c5.status_inc": "三个职位均无定论",
"c5.status_cargo": "各职位的结果",
"c5.dica.titulo": "{cargo}：{versao}",
"c5.dica.coef10": {"t": "每10个百分点的系数", "rotulo": 30},
"c5.fig1.titulo": "三个职位中，所有置信区间都跨过零",
"c5.fig1.titulo_muda": "结果因职位而异",
"c5.fig1.sub": "各职位潜在优势与两人之间卢拉占比变化的关联：潜在优势每10个百分点的效应，附95%置信区间。",
"c5.fig1.leitura": "每一行是检验的一个版本：点是估计值，线段是95%置信区间。所有区间都跨过零，而且都很窄：即使存在关联，也很小。弗拉维奥的镜像检验把同一个问题转向右翼阵营。",
"c5.fig1.aria": "分裂投票检验的估计值与95%置信区间，按职位",
"c5.fig1.eixo": {"t": "潜在优势每10个百分点的效应（卢拉占比，百分点）", "rotulo": 60},
"c5.fig1.esq": {"t": "← 与预期相反", "rotulo": 26},
"c5.fig1.como1": "**左翼得票占比** = 该职位左翼阵营政党的得票 ÷ 该职位的有效票。阵营划分来自专家调查（2022年调查）：在0～10的左右翼光谱上位置不超过{corte}的政党。没有任何政党落在{v0}与{v1}之间，这一区间内的任何分界点都给出同样的分类：分界点不取决于细微的选择。",
"c5.fig1.como2": "**潜在优势** = 左翼得票占比 − 首轮卢拉在有效票中的占比，按市镇计算。",
"c5.fig1.como3": "检验：用潜在优势解释卢拉占比的变化，以首轮卢拉占比为控制变量，比较同一州内的市镇，按合格选民人数加权，采用按州聚类的稳健标准误。",
"c5.fig1.como4": "弗拉维奥的镜像检验：右翼得票占比 − 弗拉维奥在有效票中的占比，用来解释他的占比变化。",
"c5.fig1.fonte": "来源：巴西高等选举法院（TSE），分市镇结果与各政党得票；Bolognesi、Ribeiro、Codato和Silva（2025）；本研究计算。",
"c5.lado.tit": "局限",
"c5.lado.1": "这是市镇之间的关联：它不能说明在众议员选举中投给该阵营政党的选民，就是在总统选举中改变投票的那些人。",
"c5.lado.2": "参议员选举中，{ufs}未计入：这些州左翼阵营的得票不到5%（原因是缺少候选人，而不是缺少选票）。",
"c5.chegou.texto": "在众议员或参议员选举中本来投票给左翼阵营政党、但在首轮总统选举中没有投给卢拉的地方，卢拉在第二轮增长更多。",
"c5.chegou.teste": "**主检验：**对每个职位，用潜在优势解释卢拉占比的变化，以首轮卢拉在有效票中的占比为控制变量，比较同一州内的市镇。众议员和参议员的候选人在整个州内都相同，比较同一州内的市镇，可以把选民的投票与候选人的供给区分开。预期：系数为正。联邦众议员是事先确定的主要职位：它在全国都有，包括联邦区，而且每位选民只投一票；三个职位之间不做多重比较校正，如果三者结果不一致，以联邦众议员为准。",
"c5.chegou.cargo": "{cargo}潜在优势每10个百分点，系数为{coef}个百分点（95%置信区间：{ic}）；聚类野自助法p值：{p}。{porque}分类：{classe}；{conf}。",
"c5.chegou.unica": "**唯一偏离零的版本**是同时控制其他候选人得票的版本，出现在联邦众议员和州议员选举中：符号与预期相反，效应很小。以卢拉在有效票中的占比为控制变量时，潜在优势的系数与左翼得票占比的系数相同：这项计算衡量的是卢拉占比相同的市镇之间对该阵营的投票。再把其他候选人的得票也纳入控制，剩下的效应很小且为负。稳健性检验不改变分类。",
"c5.chegou.todas": "所有版本，{cargo}",
"c5.chegou.tabela": "{cargo}：所有版本（潜在优势每10个百分点的系数；连续光谱按光谱每1分计）",
"c5.texto.1": "比较首轮卢拉占比相同的同州市镇，联邦众议员选举中对左翼阵营政党的投票与卢拉占比的变化并无关联：潜在优势每10个百分点，变化在{f0}至{f1}个百分点之间。区间很窄，围绕在零附近；州议员（{e0}至{e1}）和参议员（{s0}至{s1}）、连续光谱、2018年光谱、Partido Missão和司法待决选票的处理规则，以及以右翼阵营做的弗拉维奥镜像检验，也都如此。",
"c5.ressalvas.secao": "注意事项",
"c5.ressalvas.n12": "注释N12",
"c5.ressalvas": "司法待决（sub judice）选票：与官方结果一样，不计入有效票；含与不含这些选票的两项稳健性检验结果相同{n02}。Partido Missão在光谱上没有位置：其选票计入有效票，但不算入左翼阵营；把它的选票排除在外的稳健性检验结果相同{n11}。专家意见较不一致的政党：{n12}。",

