"c6.fig1.leitura": "每根柱表示一个地方卢拉−弗拉维奥票差的变化：从首轮的{m1}开始，累计到第二轮的{m2}。红色柱：票差向有利于卢拉的方向变化；蓝色柱：向有利于弗拉维奥的方向变化。",
"c6.fig1.como1": "**对逆转的贡献率** = 该地卢拉−弗拉维奥票差的变化 ÷ 全国的变化。",
"c6.fig1.como2": "例如{uf}：{dm} ÷ {br} = {peso}。",
"c6.fig1.como3": "计入海外票后，各地贡献率合计100%。这是完整计票，没有误差范围。",
