"c6.lado.1": "贡献率取决于合格选民的多少：即使卢拉占比的变化相近，大州的贡献率也更高。要比较各地卢拉占比变化了多少，请看“查看详情”中表格的最后一栏。",
"c6.lado.2": "只有一个州的领先方发生了变化：{uf}，弗拉维奥在首轮领先，卢拉在第二轮领先。卢拉在{l2}个州领先，弗拉维奥在{f2}个州领先；没有一个州转为弗拉维奥领先。在市镇层面，卢拉占比在{tot}个市镇中的{sub}个上升，弗拉维奥占比在{fsub}个上升。",
"c6.texto.concentra": "不计海外票，票差变化的一半来自{n50}个市镇，四分之一来自{n25}个市镇。在{neg}个市镇，票差向有利于弗拉维奥的方向变化，合计{sneg}票。",
