// --- Capítulo 9: a exploração guiada (T33; HIPOTESES.md, seção 8, rodada 1) ---
"c9.pergunta": "数据还显示了什么？",
"c9.curto": {"t": "数据还显示了什么", "rotulo": 30},
"c9.resposta": "我们在看到结果之后分两批提出了10个问题。最明确的答案是：在{fl}个市镇，卢拉由落后弗拉维奥转为领先；在{lf}个市镇，弗拉维奥由落后卢拉转为领先。其他候选人的选票并未偏向同一方：按投票站计算，Augusto Cury的选票相抵后偏向卢拉，Ronaldo Caiado的偏向弗拉维奥。首轮投票中，70岁及以上的选民只有略过半数参加投票（{p70}）。",
"c9.rotulo.cab": "探索性分析，未在计算前登记。",
"c9.rotulo.texto": "本章的问题是在看到第1至8章的结果之后分两批提出的，并与作者一起选定。每个问题都在计算前登记了检验方法和何为发现的标准；所有问题都列在这里，无论有无发现。",
"c9.rotulo.res": "结果：第1批中，4个有估计值的问题里有{n}个有发现，{s}个没有确定答案（另一个是计数）；第2批为4项计数和1项估计，{r2}。在看过数据后提出的多个问题中，可能有某个问题因偶然而得出发现。",
"c9.rotulo.curto": "探索性分析，未在计算前登记。",
"c9.cand.70": {"t": "Augusto Cury (Avante)", "fixo": true},
"c9.cand.70.curto": {"t": "A. Cury", "fixo": true},
"c9.cand.14": {"t": "Renan Santos (Missão)", "fixo": true},
"c9.cand.14.curto": {"t": "R. Santos", "fixo": true},
"c9.cand.55": {"t": "Ronaldo Caiado (PSD)", "fixo": true},
"c9.cand.55.curto": {"t": "R. Caiado", "fixo": true},
"c9.cand.resto": {"t": "其他7位候选人合计", "rotulo": 30},
"c9.cand.resto.curto": {"t": "其他7人", "rotulo": 16},
"c9.e1.p": "其他每位候选人的选票流向了哪一方？",
"c9.e1.r": "并未流向同一方：Augusto Cury的选票大部分流向卢拉（{l70}）；Ronaldo Caiado的选票（{f55}）和7位较小候选人合计的选票（{fresto}）大部分流向弗拉维奥；Renan Santos的选票没有明确方向（图{fig}）。",
"c9.e2.p": "在多少个市镇，两人的领先方发生了改变？",
"c9.e2.r": "在{fl}个市镇，卢拉由落后弗拉维奥转为领先，这些市镇共有{el}名选民；在{lf}个市镇，弗拉维奥由落后卢拉转为领先，共有{ellf}名选民。两人中卢拉的占比在{tot}个市镇中的{sub}个上升，弗拉维奥的占比在{caiu}个上升。这是计数，不用模型（图{fig}）。",
"c9.e3.p": "在州长选举有第二轮的州，弃权率的变化有所不同吗？",
"c9.e3.r": "没有明确差异。弃权率平均变化在这6个州为{a1}，在其他21个州为{a2}；这一差异可能只是偶然，而且在比较同一地区内的州时消失。",
"c9.e4.p": "投票人数在卢拉较强的地方增长更多，还是在弗拉维奥较强的地方增长更多？",
"c9.e4.r": "在卢拉较强的地方略多：比较同一市镇内的投票站，首轮卢拉得票最多的四分之一投票站，弃权率比弗拉维奥得票最多的四分之一多下降{iq}，差异很小（图{fig}）。",
"c9.e5.p": "比较同一市镇内的投票站，两人是否也都在各自较弱的地方增长更多？",
"c9.e5.r": "没有确定答案。不校正时，答案是肯定的，与市镇之间的情况一样（第1章）；按计算前登记的偶然性校正，结果相反，但当两轮的选民相同时，这种校正往往校正过度（“查看详情”，第5个问题）。",
