"c9.fig5.leitura": "这是人数统计，按登记册中的性别。显示的是谁去投票，而不是投给了谁。",
"c9.fig5.aria": "点：首轮女性和男性参加投票的比例，按年龄，全国",
"c9.fig6.titulo": "在老年登记选民较多的投票站，弃权率下降略多，卢拉的占比上升略少",
"c9.fig6.sub": "从首轮到第二轮的变化（百分点），投票站登记选民中60岁及以上者的比例每高10个百分点，比较同一市镇内的投票站。标记为97.5%置信区间。",
"c9.fig6.leitura": "在零的左侧，表示在老年登记选民较多的投票站变化较小：弃权率下降更多，卢拉的占比上升更少（弗拉维奥的占比下降更少）。适用于投票站，不适用于个人。",
"c9.fig6.eixo": {"t": "老年比例每高10个百分点，变化（百分点）", "rotulo": 56},
"c9.fig6.grupo_a": "弃权率的变化",
"c9.fig6.grupo_s": "两人中卢拉占比的变化",
"c9.fig6.aria": "系数及区间：60岁及以上登记选民比例每高10个百分点时，弃权率和两人中卢拉占比的变化，全国及各地区",
"c9.fig6.fonte": "来源：巴西高等选举法院（TSE），分投票站选民概况（2026年7月选民登记册）及两轮分投票站结果（{sec}个投票站）；本研究计算。",
"c9.fig6.como1": "计算方法：在每个投票站，以60岁及以上登记选民的比例对弃权率的变化和两人中卢拉占比的变化做回归，加入市镇固定效应（只比较同一市镇内的投票站），并按首轮合格选民人数加权。对弗拉维奥而言，是从另一侧读同一条直线。",
"c9.fig6.como2": "区间：自助法{n}次重复，按整州抽样；因有两项指标，区间为97.5%。稳健性检验见“查看详情”：区间全部低于零。",
"leg.ic975": {"t": "97.5%置信区间", "rotulo": 22},
"tab.ic975": {"t": "97.5%置信区间", "rotulo": 28},
"c9.det.i1": "**计算方法：**高等选举法院按年龄公布有多少合格选民参加了投票、多少没有投票。这里计算每个年龄组中参加投票的比例，各州相加，海外另计，只有首轮：第二轮的数据没有公布。这是人数统计，不用模型。**核对：**全国含海外，概况数据中有{pa}名合格选民和{pc}名投票者，官方结果为{oa}和{oc}。在各个市镇，数字并不一致，因为概况把{tte}名异地投票选民计入原籍市镇；因此，这里不按市镇列出任何结果（{n24}）。在自愿投票的年龄（16岁、17岁和70岁及以上），没有人列在强制投票一栏；18至69岁中，{anal}名自愿投票者是文盲选民，他们在任何年龄都是自愿投票。",
"c9.tab6.titulo": "首轮各年龄组合格选民中参加投票的比例（%）",
"c9.tab6.nota": "16岁、17岁和70岁及以上：自愿投票。",
"c9.det.i2": "**计算方法：**即第6个问题的计算，用于70岁及以上的各年龄段，并找出参加投票者不到一半的第一个年龄段。**结果：**全国为80至84岁；在{lugares}，75至79岁就已如此。",
"c9.tab7.titulo": "首轮70岁及以上选民中参加投票的比例，按年龄（%）",
"c9.tab7.primeira": {"t": "从此年龄起不足半数", "rotulo": 30},
"c9.det.i3": "**计算方法：**在首轮未投票者中各年龄组所占的比例，与其在合格选民中所占的比例并列。如果所有人以相同比例未投票，两者就会相等。",
"c9.tab8.titulo": "各年龄组在首轮未投票者和合格选民中所占的比例（%）",
"c9.tab8.cel": "未投票者的{b}；合格选民的{a}",
"c9.det.i4": "**计算方法：**即第6个问题的计算，按登记册中的性别区分女性和男性；{sem}名没有该信息的合格选民不计入。",
"c9.tab9.titulo": "首轮女性和男性中参加投票的比例，按年龄（%）",
"c9.tab9.genero": {"t": "性别", "rotulo": 14},
"c9.det.i5": "**检验：**在每个投票站，以60岁及以上登记选民的比例（来自高等选举法院的分投票站选民概况，2026年7月登记册）对从首轮到第二轮的两项变化做回归：弃权率的变化和两人中卢拉占比的变化。与第4个问题一样，只比较同一市镇内的投票站，按首轮合格选民人数加权；自助法{n}次重复，按整州抽样；因有两项指标，区间为97.5%。**何为发现：**每项指标的全国区间都位于零的一侧，且在六项稳健性检验中符号和所在一侧都相同。**结果：**两项都有发现（图{fig}）。弃权率方面，60岁及以上登记选民最多与最少的四分之一投票站之间相差{iqa}，处于规则所称“较小”的边界（半个百分点）；卢拉占比方面为{iqs}，较小。把首轮卢拉占比加入同一计算，结果不变：这不是第4个问题中的那种关联换了个名字。{sp}个缺少概况数据的投票站不计入。",
"c9.tab10.titulo": "60岁及以上登记选民比例每高10个百分点时的变化，同一市镇内的投票站：计算与稳健性检验",
"c9.tab10.a": {"t": "弃权率", "rotulo": 14},
"c9.tab10.s": {"t": "卢拉占比", "rotulo": 16},
"c9.tab10.p70": "以70岁及以上代替60岁及以上",
"c9.tab10.perfil_igual_aos_aptos": "只含登记选民与合格选民相差不到5%的投票站",
"c9.tab10.sem_efeito_de_municipio": "背景：也比较市镇之间",
"c9.tab10.com_fatia_do_lula_no_1t": "背景：加入首轮卢拉占比",
"c9.limites.5": "第6至9个问题统计的是人数，但只限首轮；而且选民登记册中仍有已去世却未被删除的选民，年龄越大越多：因此这些年龄段的投票比例低于实际。",
"c9.limites.6": "第10个问题按投票站登记选民的年龄（7月的登记册）比较各投票站，而不是按实际投票者的年龄。",

