// T42: Métodos parecidos (metodos-parecidos.js), em Método e fontes
"met.mp.tit": {"t": "类似方法", "rotulo": 28},
"mp.intro": "2026年计票的其他推算，来自对媒体、GitHub及其各自网站的搜索。列在这里，是为了检验第7章中重建的推算：大多数推算把每个已计票的投票站与上一次选举中的同一投票站相比较，就像投票站层面的变化法（b），这说明这是通用的技术。没有照搬任何内容：除平均法（m）外，本研究的方法都在这些搜索之前确定。列在这里不表示本研究认同其中每一项。",
"mp.busca": "最近一次搜索：{data}。当时重新打开了所有链接。",
"mp.rot.metodo": {"t": "方法（按来源的描述）", "rotulo": 32},
"mp.rot.avaliacao": {"t": "已发表的评估", "rotulo": 24},
"mp.rot.comparacao": {"t": "与本研究的比较", "rotulo": 28},
"mp.estadao.titulo": "《圣保罗州报》（Estadão）的推算，作者Rodrigo Mahlmeister",
"mp.estadao.quem": "Rodrigo Mahlmeister，研究人员；发布于《圣保罗州报》和projecao.live/2026；BNews有报道",
"mp.estadao.metodo": "把每个已计票的投票站与同一投票站在2022年第二轮和2026年首轮的结果相比较，推算尚未计票的投票站，并给出95%置信区间；每分钟更新一次。",
"mp.estadao.avaliacao": "媒体上零散的数字：20:29，投票站计票50.76%时，卢拉51.70%（51.60%～51.80%）；最终结果为51.79%。据该报称，从计票3%起，与最终结果的差距一直不到半个百分点。完整曲线未公开。",
"mp.estadao.comparacao": "属于投票站层面变化法（b）一类。在唯一可比的时点，即计票2.42%时（51.6%），与本研究的（b）、（c）和（d）结果相同。",
"mp.teixeira.titulo": "projecao-apuracao-tse，作者G. T. Teixeira",
"mp.teixeira.quem": "G. T. Teixeira；代码发布于GitHub和Zenodo（DOI 10.5281/zenodo.23672276），1.0版",
"mp.teixeira.metodo": "按市镇和选举分区，把每个已计票的投票站与其上一轮结果配对；用可信度权重估计变化；通过模拟（蒙特卡洛）给出95%置信区间和获胜概率。2026年10月25日实时使用。",
"mp.teixeira.avaliacao": "按到达顺序重现2022年第二轮和2026年首轮，并公布了当晚的记录。论文正文由脚本生成，未作为文档发布。",
"mp.teixeira.comparacao": "与（b）和（d）最接近。在2026年计票当晚的记录中，平均误差为0.10个百分点，置信区间在每一次运行中都包含最终结果；本研究的（b）和（d）误差为0.07和0.06，但（d）的区间在75%的读数中包含最终结果。这一比较是近似的：他的分段按合格选民的%划分，本研究的按投票站的%划分。",
"mp.aberta.titulo": "Apuração Aberta，作者Diogo Machado",
"mp.aberta.quem": "Diogo Machado；独立网站，1.29版",
"mp.aberta.metodo": "把每个已计票的投票站与其首轮结果相比较，以此为基础推算尚未计票的投票站，并区分每个州的首府和州内其他地区；显示一个可能区间。",
"mp.aberta.avaliacao": "自称在2014、2018和2022年第二轮投票中，计票20%时平均误差为0.1个百分点（最差为2014年的0.5个百分点）。该区间是用这几年的数据校准的。",
"mp.aberta.comparacao": "属于投票站层面变化法（b）一类。本研究对2022年和2018年的检验在运行前写好了规则；他的方法在相同年份中校准并评估。",
"mp.setup.titulo": "setup.news的推算",
"mp.setup.quem": "setup.news；Times Brasil有报道",
"mp.setup.metodo": "按州、首府和州内其他地区，将约47万个投票站中的每一个与其首轮结果相比较；只有当整个不确定性区间都位于50%的一侧时，才判定胜者。",
"mp.setup.avaliacao": "当晚计票4.7%时，卢拉51.86%（50.33%～53.39%）；计票13.1%时判定胜者（51.73%）。没有在其他选举中的评估。",
"mp.setup.comparacao": "属于投票站层面变化法（b）一类。以不确定性区间为依据的规则，类似于本研究检验过的按差距判定胜者的规则，后者在留出的选举中未达到目标；{secoes}个投票站规则在总统和州长选举中判定胜者时，计票比例的中位数为{mpg}。",
"mp.apura.titulo": "Apura Brasil",
"mp.apura.quem": "Apura Brasil；网站",
"mp.apura.metodo": "从最早的投票机开始进行统计推算；方法说明在另一个页面，本研究未核查。",
"mp.apura.avaliacao": "自称用2018和2022年的数据做了4000多次测试，置信度95%，没有一次判错当选者，并在2022年计票4%时就判断正确。没有公布细节。",
"mp.apura.comparacao": "没有公布方法和测试，无法比较。",
"mp.prumo.titulo": "Prumo，Brasil Paralelo出品",
"mp.prumo.quem": "Brasil Paralelo；首轮",
"mp.prumo.metodo": "使用高等选举法院的数据和数学模型估计尚未计票的投票机；没有更多细节。",
"mp.prumo.avaliacao": "首轮计票10%时，给出80%的概率进入第二轮。没有公布评估。",
"mp.prumo.comparacao": "只涉及首轮且没有方法说明，无法比较。",
"mp.nosso": "**本研究独有的内容：**按高等选举法院收到每份投票机结果单的时间重建当晚的计票；在2022、2018和2024年的检验，规则在运行前写好；以及与实时页面所用算法的比较。",
"met.ee.tit": {"t": "外部研究", "rotulo": 28},

