// ---------- Passo a passo (metodo.js) ----------
"met.passo.intro": "从高等选举法院的文件到屏幕上的数字，按计算运行的顺序排列。每一步是一个Python脚本，读取上一步的结果，核对读入的内容，并写出一个新文件；按顺序运行，可从原始文件重做全部计算。页面不做新的计算：它读取最后一个文件，并在显示时对每个数字只取整一次。",
"met.passo.n": "第{n}步",
"met.passo.cadeia_aria": "第{n}步的脚本和文件",
"met.passo.baixar": "下载：{arquivos}。",
"met.passo.repo": "脚本、脚本写出的数据集和假设登记都在{repo}中，附从来源重做全部计算的步骤说明。页面使用的数据集也可在{baixar}中获取。",
"met.passo.1.tit": "下载首轮数据并核对",
"met.passo.1.txt": "首轮总统选举结果，逐个市镇，来自高等选举法院的官方文件。{mun}个市镇的合计等于各州合计、全巴西文件和官方结果。",
"met.passo.2.tit": "下载第二轮数据并核对",
"met.passo.2.txt": "第二轮同样处理，投票机计票100%并完成最终汇总，空白票和无效票分开。合计在每个州和全巴西都与官方结果一致，市镇也与首轮相同。",
"met.passo.3.tit": "合并两轮",
"met.passo.3.txt": "两轮并列，加上本研究的计算：占比、占比变化、新增票数、票差、对逆转的贡献率、新增票占比和弃权。每个市镇标注地区、首府或州内其他地区以及规模。在每个地方，两人的新增票数都等于首轮其他候选人的票数，加上投票人数的变化，减去空白票和无效票的变化；脚本核对这一等式的余数为零。",
"met.passo.4.tit": "汇总首轮各党得票",
"met.passo.4.txt": "联邦参议员、联邦众议员、州议员和联邦区议员的选票，按市镇和政党，来自高等选举法院的开放数据。每个州的合计在108组州与职位组合（27个州×4个职位，包括同一文件中的州长）中逐党等于该州的官方结果。",
"met.passo.5.tit": "确定政党位置",
"met.passo.5.txt": "各政党的位置来自专家调查（{partidos}）。据此，脚本按市镇和职位计算左翼阵营政党的得票%（右翼阵营的%为100%减去该值和无位置政党的%）、连续光谱和潜在优势，并将专家平均值与已发表的表格核对。",
"met.passo.6.tit": "检验假设并估计区间",
"met.passo.6.txt": "第1、3、4、5章的回归，第8章社会数据的35项检验（IBGE数据在任何交叉分析之前按IBGE代码与市镇合并），关于选票来源的生态回归（按地点，使用高等选举法院的投票站数据，事先整理并核对），漏斗图和推算误差，均按在用第二轮分市镇数据做任何计算之前登记的规则进行（{incerteza}）。最后是引导式探索（第9章）的五个问题，在运行前登记，但在看到结果之后。",
"met.passo.7.tit": "记录实时计票",
"met.passo.7.txt": "在第二轮计票期间，一个页面读取高等选举法院的结果，在已计票合格选民比例相同的情况下把计票与首轮比较，推算最终结果，并记录每一次读数。首轮的投票机结果单按到达顺序累加，得出按计票%的首轮计票。记录和{como}见“实时计票”页面。",
"met.passo.7.como": "页面如何运作",
"met.passo.8.tit": "从数据集到页面",
"met.passo.8.txt": "最后一步读取上述文件，写出页面数据、各州地图（基于IBGE边界图）和可下载的文件。它根据票数用完整数值重新计算占比和变化，并与数据集核对（注释{n18}）。",

