"met.ctx.partidos.html": "调查之后的政党变化（注释<a href=\"#metodo/nota-N10\">N10</a>和<a href=\"#metodo/nota-N11\">N11</a>）：PRD，<a href=\"https://www.opovo.com.br/noticias/brasil/2023/11/09/tse-aprova-criacao-do-prd-resultado-de-fusao-entre-ptb-e-patriota.html\">O Povo</a>；Podemos和PSC，<a href=\"https://congressoemfoco.com.br/noticia/7707/com-incorporacao-do-psc-podemos-quase-dobra-filiados-em-ano-pre-eleitoral\">Congresso em Foco</a>和<a href=\"https://www.tre-es.jus.br/jurisprudencia/decisoes-em-destaque/arquivos-decisoes-em-destaque/2023/tre-es-acordao-0600021-46-justa-causa-para-desfiliacao-partidaria\">TRE-ES</a>；Solidariedade和PROS，<a href=\"https://www.tse.jus.br/comunicacao/noticias/2023/Fevereiro/partido-republicano-da-ordem-social-pros-e-incorporado-ao-solidariedade\">TSE</a>和<a href=\"https://agenciabrasil.ebc.com.br/politica/noticia/2023-02/tse-aprova-incorporacao-do-pros-ao-solidariedade\">Agência Brasil</a>；Democrata（原PMB），<a href=\"https://www.tse.jus.br/comunicacao/noticias/2025/Dezembro/partido-da-mulher-brasileira-pmb-passara-a-se-chamar-democrata\">TSE</a>和<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/partido-da-mulher-brasileira-passa-a-se-chamar-o-democrata-e-tem-nova-direcao-no-ceara-1.3730222\">Diário do Nordeste</a>；Mobiliza（原PMN），<a href=\"https://www.tse.jus.br/partidos/partidos-registrados-no-tse/arquivos-1/estatuto-do-partido-de-25-7-2021-formato-pdf-aprovado-parcialmente-em-5-12.2023/@@download/file/folha-de-rosto-e-estatuto-do-pmn-deferido-em-5-12-2023.pdf\">TSE存档的党章</a>和<a href=\"https://www.tse.jus.br/comunicacao/noticias/2023/Dezembro/plenario-decide-que-pmn-so-pode-manter-uma-entidade-de-direito-privado-destinada-a-pesquisa\">TSE</a>；Missão，<a href=\"https://www.tse.jus.br/comunicacao/noticias/2025/Novembro/tse-aprova-registro-e-homologa-estatuto-do-partido-missao\">TSE</a>和<a href=\"https://www.oliberal.com/politica/tse-aprova-registro-do-partido-missao-criado-pelo-mbl-legenda-usara-numero-14-1.1045589\">O Liberal</a>。",
