// ---------- Classificação dos partidos (metodo.js) ----------
"met.partidos.quem.html": "每个政党的位置来自一项对政治学者的调查：Bruno Bolognesi、Ednaldo Ribeiro、Adriano Codato和Bruno Fernando da Silva，“O desaparecimento do centro ideológico no sistema partidário brasileiro: a classificação mais atualizada dos experts”〔巴西政党体系中意识形态中间派的消失：专家的最新分类〕，<i>Opinião Pública</i>，第31卷，e31120，2025年（<a href=\"https://doi.org/10.1590/1807-0191202531120\">doi:10.1590/1807-0191202531120</a>）。答卷数据库在Harvard Dataverse公开（<a href=\"https://doi.org/10.7910/DVN/MFIXKW\">doi:10.7910/DVN/MFIXKW</a>），采用CC0许可。",
"met.partidos.como": "2022年7月，每位专家把每个已登记的政党放在一条从0（极左）到10（极右）的直线上。数据库中有这次调查的571名受访者（论文正文给出的数字较小；计算以数据库为准），每个政党获得398至509个评分。政党的位置是评分的平均值：本研究根据数据库计算平均值，并逐个政党与论文表格核对。",
"met.partidos.porque": "这项调查由同一团队于2018年进行，2022年再次进行，新增一名作者；目前还没有2026年的调查。本研究采用2022年的调查，它离这次选举最近，并且已经包含2018年时还不存在的政党，如União Brasil和UP。2018年和2022年是调查的年份：所有选票都来自2026年。",
"met.partidos.corte": "**左翼阵营**是位置不超过{corte}的政党，即论文所称的极左、左翼和中左政党；其他有位置的政党构成**右翼阵营**，用于弗拉维奥的镜像检验；没有位置的Missão不属于任何一方。分界点和下面的规则都在用选票做任何计算之前确定，没有任何位置出自本研究自己的判断。",
"met.partidos.regras_tit": "调查之后发生变化的政党",
"met.regra.R1": "**R1. 同一政党：**采用调查中的位置。",
"met.regra.R2": "**R2. 只改了名称：**采用原名称的位置。Mobiliza即原PMN；Democrata即原PMB。",
"met.regra.R3": "**R3. 合并：**采用参与合并各党位置的平均值。PRD采用PTB和Patriota的平均值。",
"met.regra.R4": "**R4. 并入：**采用吸收方的位置。Podemos吸收了PSC；Solidariedade吸收了PROS。",
"met.regra.R5": "**R5. 调查之后成立的政党：**没有位置。Missão属于这种情况（注释{n11}）。",
"met.regra.R6": "**R6. 政党联合会（federação）：**每个政党保留自己的位置。2026年的5个联合会中，每个联合会的所有政党都在分界点的同一侧。",
"met.partidos.tab": "2026年的30个政党，按2022年调查从左到右排列",
"met.col.numero": {"t": "序号", "rotulo": 4},
