"met.sim": "是",
"met.nao": "否",
"met.sem_posicao": "无位置",
"met.nao_existia": "当时不存在",
"met.cat.extrema esquerda": "极左",
"met.cat.esquerda": "左翼",
"met.cat.centro-esquerda": "中左",
"met.cat.centro-direita": "中右",
"met.cat.direita": "右翼",
"met.cat.extrema direita": "极右",
"met.partidos.pe": "光谱位置：评分的平均值，从0（极左）到10（极右）；光谱上的细线标出左翼阵营的分界点。评分数：给该党打分的专家人数；PRD没有自己的评分，因为它的位置是PTB和Patriota的平均值。2018年：上一次调查中的位置，仅供核对。按2018年的调查，Rede和PV位于中间，左翼阵营将是8个政党，而不是11个。专家对某些政党的看法比对另一些政党更一致（注释{n12}）。",
"met.partidos.conf.html": "核对：同一调查的2018年数据（Bolognesi、Ribeiro和Codato，2023，<i>Dados</i>，第66卷第2期，<a href=\"https://doi.org/10.1590/dados.2023.66.2.303\">doi:10.1590/dados.2023.66.2.303</a>），它是第5章检验的版本之一，得出的全国联邦众议员选举中左翼阵营的得票占比为{pct18}，而不是{pct22}；以及Cesar Zucco和Timothy Power（2024）根据对联邦众议员和参议员的调查编制的光谱（“The ideology of Brazilian parties and presidents: a research note on coalitional presidentialism under stress”，<i>Latin American Politics and Society</i>，第66卷第1期，第178–188页，<a href=\"https://doi.org/10.1017/lap.2023.24\">doi:10.1017/lap.2023.24</a>；数据见<a href=\"https://doi.org/10.7910/DVN/6KVTUV\">doi:10.7910/DVN/6KVTUV</a>），它把两者共有的16个政党排成几乎相同的顺序（斯皮尔曼等级相关系数为{rho}）。",

// ---------- Hipóteses e incerteza (metodo.js) ----------
"met.inc.contagem": "**计数没有误差范围。**选票、占比、变化、新增票占比、对逆转的贡献率和弃权，都是对TSE汇总的完整结果所做的计算，不带“±”。只有估计值才有区间。",
"met.inc.antes": "**事先登记的假设。**第1、3、4、5章各检验一个假设。每个假设连同检验方法和怎样才算获支持，都在用第二轮分市镇数据做任何计算之前写好；即使假设未获支持，结果也照样列出。规则也事先确定：纳入哪些单位、权重、分界点和精度标准。看到结果之后改动的内容都已说明并给出原因，符合登记的良好做法（Nosek et al., 2018）：一条扩展的规则（注释{n16}）；一份统计审稿意见要求的修正（涉及所显示的区间、生态回归、精度标准和漏斗图）；以及在分地区估计中，用同一市镇内投票站之间的计算替换市镇之间的计算，这一计算事先登记，在看到结果之后选定。这些改动都没有改变任何假设的判定。事后计算、未经登记的内容列为探索性分析。",
"met.inc.teste": "**检验方法。**在市镇之间做回归，按首轮合格选民人数加权。起决定作用的版本把每个市镇与同州的其他市镇比较，从而去掉全州共有的因素，如州长候选人和各政党在当地的实力；把全国所有市镇放在一起的版本列在旁边。标准误按州聚类，95%置信区间使用自由度为州数减1的t分布（Bester、Conley和Hansen，2011；Cameron和Miller，2015）。加权使计算衡量的是平均选民层面的关联，而不是平均市镇层面的关联；因此不加权的版本也列在旁边（Solon、Haider和Wooldridge，2015）。",
"met.inc.poucos": "**聚类数少。**共27个州（州内比较中为26个），但按合格选民人数加权后，权重集中在少数几个州：São Paulo占{sp}，最大的8个州占{oito}。有效聚类数（Carter、Schnepel和Steigerwald，2017）在{gmin}到{gmax}之间，视假设和前提而定；有效聚类这么少，聚类标准误的区间往往过窄。因此每项检验还使用施加原假设的聚类野自助法，在各聚类规模差异很大时，正是它提供保护（MacKinnon和Webb，2017），采用Webb权重和{rep}次重复（Cameron、Gelbach和Miller，2008；Webb，2023；MacKinnon、Nielsen和Webb，2023）。图表和简短回答显示的是这一自助法的区间，通过检验反演求得；表格同时显示两种区间。",
"met.inc.classe": "**判定。**获支持：两个95%区间，即自助法区间和聚类标准误区间，都完全落在预测的一侧（p值低于{p}时，自助法区间不含零）。被反驳：同上，但落在相反的一侧。无定论：其中一个区间包含零。同时给出大小，用四分位距效应衡量：低于{pp}时，称关联较小。稳健性检验的版本（不加权、全国、其他光谱、其他数据规则）不改变判定；各章说明结果在其中多少个版本中保持不变。四个假设之间不做多重比较校正，因为每个假设都是单独的论断（Rubin，2021）。",
"met.inc.sociais": "**社会数据（第8章）。**市镇的7项特征，每项对照5个选举指标：共35项检验，在做任何交叉分析之前登记，不预设方向。回归与假设检验相同，每次一项特征，在州内进行。检验这么多，有些会偶然显示关联；因此每项检验的p值都用Holm（1979）的方法校正，只有当自助法和聚类标准误的校正后p值都低于{p}时，才说存在关联。",
"met.inc.ecologica": "**选票从哪里来。**生态回归（Goodman，1953和1959）：用其他候选人首轮的票数、投票人数的变化和空白票与无效票的减少，来解释每位候选人新增的票数，全部除以合格选民人数，并按合格选民人数加权。每个来源中两人所占部分合计为100%。分地区（全国、各地区和各州）时，计算比较同一市镇内的投票站（{sec}个投票站），并加入市镇效应：影响整个市镇的变动被排除在外，变化中全市镇共有的一部分不归入任何来源（全国相抵后为卢拉{comum}票，即第二轮新增票数的{pct}）。这种计算事先登记，并在看到结果之后替换了市镇之间的计算：用它，没有任何估计值超出0%到100%；用另一种，几乎所有地方都有某项估计值超出。区间来自{rep}次自助法重复：全国和各地区按整个州抽样；各州按整个市镇抽样。对于全国其他候选人的选票，无截距的市镇间计算、有截距的计算、转移矩阵（Romero et al., 2020）和按投票站的计算给出不同的划分，有的高于一半，有的低于一半，第3章列出全部四种。",
"met.inc.criterio": "**精度标准**，对两位候选人相同：某地的估计值只有同时满足以下条件才显示：该地至少有30个市镇，估计值在0%到100%之间，且95%置信区间的半宽不超过10个百分点。超出0%到100%不是精度不足，而是模型不能描述该地的信号，此时该地的所有来源都加上†标记，即使是通过了的来源。没有通过的地方，页面显示“无法可靠估计”及原因（{lista}）。",
"met.inc.funil": "**漏斗图。**带状区域显示该规模的市镇通常的变动幅度：取决于合格选民人数的偶然误差，加上所有市镇共有的一项变动，后者用全部市镇的数据估计，方法同Spiegelhalter（2005b），但不截去两端（截去两端时，中等和大型市镇的带状区域过窄）。这是筛查，用来决定仔细查看哪些市镇（Spiegelhalter et al., 2012）：一个市镇落在带外，单凭这一点不能证明任何事。",
"met.inc.projecao": "**实时推算。**误差是测量出来的，不是估计出来的：在记录下来的每个读数中，用推算值减去最终结果。这只是一个晚上的误差：这些读数是一条轨迹，不是独立样本，不能衡量该方法在其他选举中的精度。",
"met.inc.semente": "抽样使用固定的随机种子20261026，与结果一起保存，使计算每次都得到相同的数字。",
"met.inc.ref_tit": "方法参考文献",
