"met.dados.repo": "每个文件的生成方式：{passo}。",
"rod.texto.html": "<i>巴西第二轮投票的逆转</i>，2026年总统选举：从首轮到第二轮发生了哪些变化，按州和市镇。另见<a href=\"#metodo/sobre\">关于本研究</a>、<a href=\"#metodo/dados\">数据下载</a>、逐次读数的<a href=\"#apuracao\">第二轮实时计票</a>，以及<a href=\"privacidade/\">隐私</a>页面。",
"rod.escrever": "给作者写信",
"rod.fechar": {"t": "关闭", "rotulo": 12},
"rod.contato_curto": {"t": "联系", "rotulo": 10},
