"exp.ponte.intro": "两人的票差从首轮的{m1}变为第二轮的{m2}。瀑布图把每个地区或每个州的部分加总起来。",
"exp.ponte.leitura": "计算从首轮的票差（{m1}）开始，逐一加上每个地方的变化，直到第二轮的票差（{m2}）。红色柱：票差向有利于卢拉的方向变化；蓝色柱：向有利于弗拉维奥的方向变化。将鼠标悬停或点按某一柱可查看数字。",
"exp.ponte.como1": "**票差变化** =（第二轮卢拉−弗拉维奥）−（首轮卢拉−弗拉维奥），以票数计，按每个地方计算。加总后得到全国的变化：{dm}票。",
"exp.ponte.como2": "**对逆转的贡献率** = 该地的变化÷全国的变化。各地贡献率合计为100%，包括海外。",
"exp.ponte.sub_reg": "票差瀑布图：从首轮到第二轮卢拉−弗拉维奥的票差（以票数计），按地区加总。",
"exp.ponte.sub_uf": "票差瀑布图：从首轮到第二轮卢拉−弗拉维奥的票差（以票数计），按州加总。",
