"exp.mapa.modo_da": {"t": "弃权率变化", "rotulo": 24},
"exp.mapa.titulo_s1": "首轮投票中，卢拉在{l}个州得票多于弗拉维奥；弗拉维奥在{f}个州得票多于卢拉",
"exp.mapa.titulo_s2": "第二轮投票中，卢拉在{l}个州得票多于弗拉维奥；弗拉维奥在{f}个州得票多于卢拉",
"exp.mapa.titulo_ds": "在{onde}，卢拉占比上升、弗拉维奥占比下降，幅度为{min}至{max}个百分点",
"exp.mapa.titulo_da": "弃权率在{caiu}个州下降，在{subiu}个州上升",
"exp.mapa.sub_s1": "首轮各州两人之间的占比：卢拉得票较多的州为红色，弗拉维奥得票较多的州为蓝色；颜色越深，领先幅度越大。接近50%时颜色较浅，但颜色仍显示谁领先。",
"exp.mapa.sub_s2": "第二轮各州两人之间的占比：卢拉得票较多的州为红色，弗拉维奥得票较多的州为蓝色；颜色越深，领先幅度越大。接近50%时颜色较浅，但颜色仍显示谁领先。",
"exp.mapa.sub_ds": "从首轮到第二轮，卢拉在两人之间占比的变化，以百分点计；弗拉维奥的变化数值相同，符号相反。越红，卢拉占比上升越多。",
"exp.mapa.sub_da": "从首轮到第二轮弃权率的变化，以百分点计。颜色越深：弃权率上升越多，或下降越少；带条纹的是弃权率上升的州。不使用候选人的颜色，因为弃权不属于两人中的任何一方。",
"exp.dica.fatia_lula": {"t": "卢拉占比", "rotulo": 22},
"exp.dica.de_para_var": "{a} → {b}（{v}）",
"exp.mapa.escolha": "地图显示的内容",
"exp.mapa.leg_listras": {"t": "条纹：弃权率上升", "rotulo": 32},
"exp.mapa.aria": "各州地图。每个州都可以用键盘聚焦；按Enter键会把该州的概况卡固定在旁边。",
"exp.mapa.fonte": "来源：巴西高等选举法院（TSE），首轮和第二轮结果；IBGE的州界地图；本研究计算。",
"exp.mapa.como.tit": "各州地图的制作方法",
"exp.mapa.como1": "**占比** = 候选人得票÷（卢拉得票+弗拉维奥得票），按每一轮计算。色阶从蓝色（弗拉维奥获得两人80%的选票）到红色（卢拉获得80%），平局时为浅灰色；超过80%时颜色不再变化。",
"exp.mapa.como2": "**占比变化** = 卢拉第二轮占比−首轮占比，以百分点计。色阶向每侧最多到5个百分点。",
"exp.mapa.como3": "**弃权率** =（合格选民−投票人数）÷合格选民，按每一轮计算，各用该轮的合格选民人数；色阶从−4到+8个百分点。",
"exp.mapa.como4": "州界地图：IBGE，最低精度版本，仅用于绘制地图。",
