"exp.voto.como1": "**潜在优势** = 该职位选举中左翼阵营政党的得票% − 首轮卢拉在有效票中的占比，按市镇计。弗拉维奥的镜像检验：右翼阵营的得票% − 弗拉维奥在有效票中的占比。",
"exp.voto.como2": "检验：用潜在优势解释卢拉占比的变化，以首轮卢拉占比为控制变量，比较同一州内的市镇，按合格选民人数加权，标准误按州聚类。事先确定的规则：只有95%置信区间完全落在预测的一侧，且聚类野自助法的p值低于{p}时，才判为获支持。",
