"exp.voto.nota": "各版本改变了什么以及结论，见{link}。",
"exp.inc.vieram_tit": "新增票从何而来",
"exp.inc.vieram_sub": "巴西全国每一类新增票来源相抵后在两人之间的分配：估计值附95%置信区间。其他候选人的选票有四种算法，结果并不一致。",
"exp.inc.vieram_leitura": "其他候选人选票的分配取决于算法。在比较市镇的三种算法中，都有某一部分超出0%至100%的范围；比较同一城市内的投票站时，没有任何一部分超出，其他候选人的选票分配没有明显偏向哪一方。结论适用于地方，不适用于个人：一切都是相抵后的净变化，首轮投给其他候选人的人中，可能有一部分在第二轮没有投票，反之亦然。",
"exp.inc.vieram_como1": "**生态回归**（Goodman，1953年和1959年）：在市镇之间，用三类新增票来源解释每位候选人的新增票数，全部除以合格选民人数并以其加权；两人在每类来源中的份额合计为100%。加入截距时，一部分变化落在三类来源之外。在转移矩阵中（Romero等，2020），用首轮的各类别解释第二轮的各类别。在按投票站的算法中，使用同样三类来源，比较同一城市内的投票站，并加入市镇效应；另外两类来源的估计来自这一算法。",
"exp.inc.vieram_como2": "区间：{n}次重复的自助法，按整州重抽样。只显示满足精度标准的结果：估计值在0%至100%之间，且区间半宽不超过10个百分点。",
// a parte de quê, numa frase ("a maior parte dos votos dos outros candidatos"), e o nome da aba
