"exp.inc.lugar_como1": "**与巴西全国相同的生态回归**，比较同一城市内的投票站，加入市镇效应，按地区和按州分别计算。自助法区间：地区层面按整州重抽样；州层面按整个市镇（连同其全部投票站）重抽样。市镇间的算法与按投票站的算法得出相反方向时，视为无法估计。",
"exp.inc.lugar_como3": "只有当整个区间都高于50%时，才写“大部分归X”。",
