"exp.proj.leitura": "零的左侧表示该读数给卢拉的占比低于最终结果、给弗拉维奥的高于最终结果；右侧则相反。这是实测误差，没有误差范围。",
"exp.proj.aria": "实时推算与部分计票结果的平均误差，按计票进度区段",
