"av.dica.contagem2": {"t": "第二轮计票", "rotulo": 26},
"av.dica.mesmo_pct": {"t": "首轮（相同计票进度）", "rotulo": 28},
"av.dica.maior_erro": {"t": "此后至结束的最大误差", "rotulo": 28},
"av.dica.faixa": {"t": "范围带", "rotulo": 12},
"av.a1.aria": "第二轮计票中与首轮同一批投票机中的卢拉占比，计票进度从{de}到{ate}；变化介于{min}至{max}个百分点之间",
"av.a1.como1": "**变化** = 第二轮计票中的卢拉占比 − 同一批投票机首轮的卢拉占比，以百分点计。弗拉维奥的变化幅度相同，符号相反。",
"av.a1.como2": "**首轮按相同已计票合格选民比例**（页面称之为“同一批投票机”）：页面并非逐台投票机比较。在300个最大市镇中的每一个，以及每个州的其余部分，页面从首轮取与第二轮已计票合格选民相同的比例，然后相加。这是一种近似：它假定每个地方已计票的部分能代表该地的首轮结果；这一假定在计票初期不太成立，在各州的其余部分也不太成立，因为后者汇集了在不同时间计票的地方。",
"av.a1.como3": "数值为页面记录的数值，保留3位小数。计票100%时，同一批投票机即全部投票机，其首轮结果即为最终结果（{m}）。从{b0}到{b1}之间没有读数，那段时间高等选举法院网站开始拒绝页面的部分请求。在这一段，短划线是事后按高等选举法院收到每份投票机结果单（boletim de urna）的时间重建的读数（第7章，“查看详情”）；这些读数不计入滑尺，也不计入本页的计算。",
"av.fonte": "资料来源：实时计票页面记录的读数，依据巴西高等选举法院（TSE）的结果。",
"av.salto.tit": "{hora}实时推算为何跳变",
"av.salto.1": "{hora}，仅在一次读数中，实时推算从{de}变为{para}，并在下一次读数（{hora2}）回到{volta}。",
"av.salto.2": "事后用同一时刻的数据重建（第7章，“查看详情”），该次读数的推算为{refeita}，与相邻读数一致：跳变并非来自选票。",
"av.salto.3": "实时推算把全国的计票结果，与各州及300个最大市镇尚未计票的部分相加，后者读取自高等选举法院的不同文件。在这一次读数中，部分州的文件比其下辖市镇的文件更旧：州的其余部分几乎没有已计票的票，而根据这几乎为零的票算出的变化，被推及该地尚未计票的全部合格选民。",
"av.salto.4": "无法知道是哪个文件过旧；但机制是清楚的。",
"av.a2.contraste": "，而计票显示{quem}从{de}到{ate}领先",
"av.a2.titulo": "从结果回看：从计票{pct}起，即使出现实时推算此后直至结束的最大误差，也不会改变领先者",
"av.a2.titulo_todas": "从结果回看：在所有读数中，即使出现实时推算此后直至结束的最大误差，也不会改变领先者",
"av.a2.sub": "随着投票机陆续计票，实时推算的最终结果中的卢拉占比。范围带从推算值减去、到推算值加上该次读数直至结束期间推算的最大误差。",
"av.a2.leitura_sempre": "实时推算在所有读数中都显示{quem}领先{contraste}。",
"av.a2.leitura_antes": "计票{pct}之前，范围带仍下探至{min}。",
"av.a2.leitura_erro": "误差的大小只有在计票结束后才能知道：当时页面并不显示这一范围带。",
"av.a2.leitura_salto": "除{hora}只出现在一次读数中的跳变外{nota}，计票{pct}之前，实时推算一直低于卢拉的最终结果。",
"av.a2.aria": "卢拉占比的实时推算，计票进度从{de}到{ate}，附此后至结束的最大误差范围带；从计票{pct}起，范围带不再跨过{p50}",
"av.a2.como1": "**范围带** = 推算值 ± 该次读数到结束前最后一次读数之间的最大误差（推算值 − 最终结果，{final}）。由于使用了最终结果，它只能事后绘制；它不是置信区间。",
"av.a2.como2": "**实时推算**假定每个地方尚未计票的部分会延续首轮结果，再加上当地已观察到的变化。按计票进度区段的推算误差见第7章。",
"av.a3.titulo": "与首轮相同计票进度时相比，差异最高达{dif}个百分点；在同一批投票机中，不超过{max}",
"av.a3.sub": "第二轮计票与首轮计票在投票机计票进度相同时，卢拉在两人合计票数中的占比。",
"av.a3.leitura": "两轮投票中投票机结果到达的顺序不同：与首轮同一计票进度相比，会把选票变化与计票顺序混在一起。因此页面使用同一批投票机（图A1）。计票100%时，两种比较都得出{v}。",
"av.a3.pontos": "{n}个百分点",
"av.a3.aria": "第二轮计票与首轮相同计票进度时的卢拉占比；差异最高达{dif}个百分点",
"av.a3.como1": "**按计票进度的首轮计票**：事后根据首轮的投票机结果单重建，按到达高等选举法院的顺序累加；计票进度是已收到的投票站的合格选民所占比例。实时计票页面曾把这条曲线与计票结果一同显示。",
"av.a3.como2": "曲线两点之间，相同计票进度的数值按直线插值（曲线共有{n}个点）。曲线从{pct}开始，接近第二轮的第一次读数。",
"av.a3.fonte": "资料来源：实时计票页面记录的读数；首轮投票机结果单（巴西高等选举法院，TSE）。",
"av.fim.intro": "计票100%时，页面显示了最终结果：卢拉获得{l2}票（占两人合计票数的{s2}），弗拉维奥获得{f2}票（{sf}）。投票人数占合格选民的{c2}（首轮为{c1}）；空白票和无效票占全部选票的{bn}。下方按页面当时的列表方式，列出各州和最大市镇的最终结果；各州地图见{explorar}，投票人数见{cap4}。",
