"csv.arq.estados": "同样的列，用于全巴西、5个地区、海外和27个州（海外记为ZZ）。",
"csv.arq.partidos": "2026年的30个政党，附各党在专家调查左右翼光谱（0～10）上的位置、是否属于左翼阵营以及所用的规则。",
"csv.arq.esquerda_municipios": "首轮众议员和参议员选举中左翼阵营的得票，分市镇、州和全巴西（第5章）。弗拉维奥的镜像检验所用的右翼阵营得票，等于100%减去左翼阵营和无位置政党的得票。",
"csv.arq.hipoteses": "第1、3、4、5章各假设的检验：主检验和稳健性检验，附95%置信区间、p值和判定结果。",
"csv.arq.de_onde_vieram": "每位候选人的新增票数从何而来，分全巴西、地区和州，比较同一城市内的各投票站，附95%置信区间和精度标准。",
"csv.arq.apuracao_ao_vivo": "第二轮实时计票页面记录的读数：已计票比例（%）、时间、计票结果、同一批投票机的首轮结果以及推算值（第7章和“实时计票”）。",
"csv.arq.testes_sociais": "第8章社会数据的35项检验（7项特征×5项指标），分州内和全巴西两种，附95%置信区间、p值、经Holm校正的p值和结果。",
"csv.arq.dados_sociais": "第8章中每个市镇的7项特征（巴西地理统计局（IBGE）、2022年人口普查和2023年市镇GDP），附各项的计算基数。",
"csv.arq.dicionario": "每个文件中每一列的含义。",
