// ======================= Privacidade (privacidade/index.html; T17) =======================
"priv.titulo_pag": "隐私 · {nome}",
"priv.descricao": "您发送给本研究的数据用于什么、谁能看到、保存多久，以及如何要求删除。",
"priv.tit": "隐私",
"priv.linha_fina": "阅读本研究、下载PDF和数据，都不需要提供任何数据。本页说明您决定发送的内容会如何处理：用于什么、谁能看到、保存多久，以及如何要求删除。",
"priv.agora": "目前已开放的有：给作者的留言框、“向数据提问”中的书面提问，以及“向研究提问”按钮的助手。评论和新版本通知尚未开放：本页已说明开放后的做法。如有变化，本页会先行更新，并在末尾注明日期。",
"priv.quem.tit": "谁对数据负责",
"priv.quem": "本研究的作者Murilo Neves de Martins。他独立完成本研究，与任何政党、候选人或竞选团队都没有关联。根据巴西《通用个人数据保护法》（LGPD，第13.709/2018号法律），他是数据控制者：决定数据的用途，并对数据负责。",
"priv.ler.tit": "阅读网页时",
"priv.ler.1": "本页不使用cookie，无论是广告cookie还是跟踪cookie，也没有会记录访客的社交网络按钮。字体直接来自本研究的网址。",
"priv.ler.2": "它会在您的浏览器中保存一些选择，以便下次访问时记住：浅色或深色模式，以及您保持打开的图表和分组。这些只保存在您的设备上，不会发送给任何人；在浏览器中清除本站数据即可清除这些选择。",
"priv.ler.3": "本研究托管在Cloudflare上。和所有托管服务一样，Cloudflare会收到访问者的网络地址（IP），用于传送页面和防范攻击。访问统计（Cloudflare Web Analytics）不使用cookie，也不识别读者身份：只显示总数，例如每天的访问量、国家和设备类型。本研究还按天统计PDF的下载次数、各部分和各章节的打开次数、市镇搜索的使用次数，以及访客来自哪个推广链接（网址中的“?origem=”标记）：只记录次数，不记录网络地址、时间或任何能识别访客的信息。",
"priv.enviar.tit": "您可以发送什么，用于什么",
"priv.contato.tit": "给作者的留言：通过页脚的“给作者写信”框",
"priv.contato": "发送的内容：留言，以及（如您愿意）姓名和电子邮件。用途：供作者阅读；如留有电子邮件，作者会回复。留言经过一个表单服务（Web3Forms），它把留言送到作者的邮箱，但不显示作者的邮箱地址；留言不接受附件。直接写信到作者邮箱（地址见研究的PDF）的留言，也按同样方式处理。保存期限：最后一次通信后12个月；之后删除。",
"priv.comentarios.tit": "评论：在研究末尾",
"priv.comentarios": "发送的内容：评论、您选择的姓名或昵称（会与评论一起显示），以及（如您愿意）一个电子邮件，仅用于接收回复通知；电子邮件绝不会显示在页面上。用途：发布评论并管理讨论。每条评论在显示前都由作者阅读，并借助人工智能（Anthropic的Claude，由作者在自己的电脑上使用），它只看语气和行为，从不看政治观点。如果您在正文中写了电子邮件或电话号码，这部分不会向他人显示。网络地址只以打乱后的形式保存，用于限制每人的评论数量。每条待审核的评论，作者都会收到一封电子邮件通知，内含姓名和正文，以便尽快阅读；通知中不含您的电子邮件。保存期限：只要研究在线，或直到您删除。在您写评论的设备上，“删除我的评论”按钮会立即删除正文和姓名；在其他设备上，请联系作者。",
"priv.avisos.tit": "新版本通知：在PDF旁边",
"priv.avisos": "发送的内容：您的电子邮件和申请日期。用途：研究发布新版本时发送一封电子邮件，附上PDF和改动内容；仅此而已，没有广告，也没有其他类型的消息。每封邮件都有退订链接，点击即可把地址从名单中删除。保存期限：直到您退订，或直到研究不再发布新版本。",
"priv.pergunte.tit": "书面提问：在“探索”的“向数据提问”中",
"priv.pergunte": "发送的内容：问题的文字。用途：一个人工智能服务读取问题，只是为了判断您问的是页面上哪一个现成问题、涉及哪个地点；回答来自高等选举法院的计票，在页面本身生成。问题先发给Cloudflare的Workers AI；当天的免费额度用完后，再发给Anthropic的Claude，直到每天的支出上限。本研究不保存问题的文字：只保存每天的提问数量，以及一个由网络地址生成的打乱代码（保存到当天结束），用于限制每人的提问数量。请不要在问题中填写个人信息。",
"priv.assistente": "发送的内容：问题的文字，以及同一对话中之前的问题和回答。用途：一个人工智能服务阅读研究并写出回答，注明可以核对的段落。问题发给Ollama上的gpt-oss，在当月免费额度内使用；额度用完后，向研究提问的功能暂停到下个月。只要研究在线，本研究就会保存问题和回答，用于改进回答和整理常见问题区；常见问题区显示的是本研究改写后的问题，绝不是提问者的原文。与问题一起保存的只有日期、页面语言和问题在对话中的顺序：不保存网络地址，也不保存任何能识别提问者的信息。因此，事后无法找出某个人提的问题。为了限制每人的提问数量，会保存一个由网络地址生成的打乱代码，到当天结束为止，与问题分开存放。请不要在问题中填写个人信息。",
"priv.assistente.tit": "向助手提问：通过页面角落的“向研究提问”按钮",
"priv.robos": "在前三种情况下，一种看不见的防机器人保护会在不要求您做任何事的情况下，确认发送者是真人；在书面提问中，每人提问上限起到这个作用。以上所有处理的依据是您的同意（LGPD第7条第I款）：您是自愿发送的，可以随时撤回。",
"priv.nao.tit": "不会做的事",
"priv.nao": "数据不会出售，不会转交给任何人，也不会用于广告、选举民调或竞选活动，无论哪一方。数据不会与其他数据库交叉比对，也不会用于建立读者画像。",
"priv.servicos.tit": "还有谁会接触数据：为本研究提供服务的机构",
"priv.servicos": "只有让本研究运转的服务，各自负责自己的部分：Cloudflare（托管、数据库、防机器人保护和书面提问的读取）、留言框的表单服务（Web3Forms）、发送新版本邮件和新评论通知给作者的服务（Resend）、Ollama（助手的回答）、Anthropic（Cloudflare免费额度用完后读取书面提问，也通过作者在自己电脑上使用的Claude协助审核评论）。其中一些服务把数据保存在巴西海外。",
"priv.direitos.tit": "您的权利以及如何申请",
"priv.direitos.html": "您可以随时要求了解是否存在您的数据，查看、更正或删除这些数据，以及撤回同意（LGPD第18条）。如需申请，请通过研究页脚的“给作者写信”框，或通过<a href=\"https://www.linkedin.com/in/murilomartins/\">LinkedIn</a>联系作者。申请会在15天内处理。如需停止接收新版本通知，使用每封邮件中的链接即可。您也可以向巴西国家数据保护局（<a href=\"https://www.gov.br/anpd/\">ANPD</a>）投诉。",
"priv.data": "更新于2026年10月28日。",
"priv.voltar": "返回研究",

